sys_script_include.script:
var GlobalToolsATF = Class.create(); 
GlobalToolsATF.prototype = {
	initialize: function (sScriptIncludeName, _ScriptIncludeRef, bLog, outputs, steps, params, stepResult, assertEqual) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		this._bLog = bLog;
		this._gt = new global.GlobalTools();
		this._gtArray = new global.GlobalToolsArray();
		this._gtRead = new global.GlobalToolsRecordRead();
		this._gtWrite = new global.GlobalToolsRecordWrite();
		this._getType = this._gt.getType;
		this._sScriptIncludeName = sScriptIncludeName;
		this._ScriptIncludeRef = _ScriptIncludeRef;
		this._aErrors = [];
		this._outputs = outputs;
		this._steps = steps;
		this._params = params;
		this._stepResult = stepResult;
		this._assertEqual = assertEqual;
		this._bContinue = true;
		this._iTestCount = 0;
		if ((this._getType(sScriptIncludeName) != 'string') || (this._getType(_ScriptIncludeRef) != 'object')) {
			gs.warn('GlobalToolsATF.initialize invalid parameters sScriptIncludeName is not an string or _ScriptIncludeRef is not an object.');
			this._bContinue = false;
		} // validate input
	}, // function initialize

	_checkAccess: function (sCallerScope) {
		if (this.oAllowedScopes) { return this.oAllowedScopes.hasOwnProperty(String(sCallerScope)); }
		var aScopes = String(gs.getProperty('now.globaltools.access_from_scope')).split(',');
		var aCustomScopes = String(gs.getProperty('now.globaltools.access_from_scope_custom')).split(',');
		this.oAllowedScopes = Object.fromEntries([...aScopes, ...aCustomScopes].map(sItem => [sItem, true]));
		this.oAllowedScopes['rhino.global'] = true;
		return this.oAllowedScopes.hasOwnProperty(String(sCallerScope));
	}, // function _checkAccess

	runATF: function (sFunction, oExpectedResult) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if (this._bContinue === false) { return; }
		this._iTestCount++;
		if ((sFunction) && (this._getType(sFunction) == 'string')) {
			var aArguments = [];
			for (var i = 2; i < arguments.length; i++) {
				aArguments.push(arguments[i]);
			} // each arg after 2 mandatory params
			var sArguments = this._stringifyArgs(aArguments);
			var oResult = this._ScriptIncludeRef[sFunction].apply(this._ScriptIncludeRef, aArguments);
			var sExpectedResultType = this._getType(oExpectedResult);
			var sExpectedResultTypeComparison = '=';
			if (sExpectedResultType == 'string') {
				var reOperatorAndCount = /^([<>]=?|=)\s*([-+]?\d*\.?\d+)$/g;
				var aOperatorAndCount = oExpectedResult.match(reOperatorAndCount);
				if (this._gtArray.isValidArray(aOperatorAndCount)) {
					var reOperator = /([<>]=?|=)\s*/g;
					var reCount = /([-+]?\d*\.?\d+)/g;
					var aMatchOperator = oExpectedResult.match(reOperator);
					var aMatchCount = oExpectedResult.match(reCount);
					if ((this._gtArray.isValidArray(aMatchOperator)) && (this._gtArray.isValidArray(aMatchCount))) {
						sExpectedResultTypeComparison = aMatchOperator[0].trim(); // the g-flag match includes the whitespace after the operator
						oExpectedResult = (isNaN(aMatchCount[0])) ? '' : Number(aMatchCount[0]);
					} // if valid comparison
				} // is ops and count match is valid array
			} // if expected result is string
			var sResultType = this._getType(oResult);
			sExpectedResultType = this._getType(oExpectedResult);
			var iResultCount = -1;
			if ((sExpectedResultType == 'number') && (sResultType == 'array')) {
				iResultCount = oResult.length;
			} else if ((sExpectedResultType == 'number') && ((sResultType == 'gliderecord') || (sResultType == 'glideaggregate'))) {
				iResultCount = oResult.getRowCount();
			} else if ((sExpectedResultTypeComparison) && (sExpectedResultType == 'number') && (sResultType == 'number')) {
				iResultCount = oResult;
			} else if ((sExpectedResultType == 'number') && (sResultType == 'string') && (!isNaN(oResult))) {
				iResultCount = Number(oResult);
			} else if ((sExpectedResultType == 'string') && (sResultType == 'gliderecord')) {
				oResult = oResult.getUniqueValue();
			} else if (sExpectedResultType == 'function') {
				oResult = this._gt.runFunction(String(oExpectedResult), oResult, sResultType);
				oExpectedResult = 'function';
			} // expected type
			if (this._bLog) {
				gs.info(this._sScriptIncludeName + '.' + sFunction + ' expected result: ' + oExpectedResult + ' (' + sExpectedResultType + ' / ' + sExpectedResultTypeComparison + ')' + ' result: ' + oResult + ' (' + sResultType + ' / ' + iResultCount + ') with arguments: ' + JSON.stringify(aArguments));
			} // if log
			if (iResultCount != -1) {
				if ((sExpectedResultTypeComparison == '<') && (iResultCount < oExpectedResult)) {
					return true;
				} else if ((sExpectedResultTypeComparison == '>') && (iResultCount > oExpectedResult)) {
					return true;
				} else if ((sExpectedResultTypeComparison == '>=') && (iResultCount >= oExpectedResult)) {
					return true;
				} else if ((sExpectedResultTypeComparison == '<=') && (iResultCount <= oExpectedResult)) {
					return true;
				} else if ((sExpectedResultTypeComparison == '=') && (iResultCount == oExpectedResult)) {
					return true;
				} // result count
			} // expected number
			if ((this._gt.isEqual(oResult, oExpectedResult)) || ((sExpectedResultType == 'function') && (!oResult))) {
				return true;
			} else if ((sExpectedResultType == 'regexp') && (sResultType == 'object') && (oExpectedResult.test(JSON.stringify(oResult)) === true)) {
				return true;
			} else if ((sExpectedResultType == 'regexp') && (oExpectedResult.test(String(oResult)) === true)) {
				return true;
			} else {
				if (sResultType == 'object') {
					if (sExpectedResultType == 'regexp') {
						this._aErrors.push(this._sScriptIncludeName + '.' + sFunction + ' test counter ' + this._iTestCount + ' expected result: ' + oExpectedResult.toString() + ' (' + sExpectedResultType + ')' + ' result: ' + JSON.stringify(oResult) + ' (' + sResultType + ') with arguments: ' + sArguments);
					} else {
						this._aErrors.push(this._sScriptIncludeName + '.' + sFunction + ' test counter ' + this._iTestCount + ' expected result: ' + JSON.stringify(oExpectedResult) + ' (' + sExpectedResultType + ')' + ' result: ' + JSON.stringify(oResult) + ' (' + sResultType + ') with arguments: ' + sArguments);
					}
				} else {
					this._aErrors.push(this._sScriptIncludeName + '.' + sFunction + ' test counter ' + this._iTestCount + ' expected result: ' + oExpectedResult + ' (' + sExpectedResultType + ')' + ' result: ' + oResult + ' (' + sResultType + ') with arguments: ' + sArguments);
				} // if obj
			} // if results match
		} else {
			this._aErrors.push('GlobalToolsATF.runATF invalid sFunction: ' + sFunction);
		} // if valid params
	}, // function runATF

	_stringifyArgs: function (aArgs) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var aStringArgs = [];
		aArgs.forEach(function (sArg) {
			if (this._gt.getType(sArg) == 'object') {
				aStringArgs.push(JSON.stringify(sArg));
			} else {
				aStringArgs.push(String(sArg));
			} // if object
		}, this); // each arg
		return aStringArgs.join(' | ');
	}, // function _stringifyArgs

	getRecord: function (sTable, sQuery) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var grRecord = this._gtRead.getRecords(sTable, sQuery, null, null, 1);
		if (grRecord.next()) {
			return grRecord;
		} // if next
	}, // function getRecord

	generateTestData: function (oTestDataConfig, bError) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if ((oTestDataConfig) && (this._getType(oTestDataConfig) == 'object')) {
			Object.keys(oTestDataConfig).forEach(function (sTable) {
				var aTestDataTableConfigs = oTestDataConfig[sTable];
				if (this._gtArray.isValidArray(aTestDataTableConfigs)) {
					aTestDataTableConfigs.forEach(function (oTestDataConfig) {
						var oError = {};
						var oConfig = {
							sTargetTable: sTable,
							bInsert: true,
							bKeepSysId: true,
							aQueryFields: ['sys_id', 'name', 'user_name', 'short_description', 'number', 'asset_tag'],
						}; // config
						var sSysId = this._gtWrite.doRecord(oTestDataConfig, oConfig, oError);
						if (sSysId) {
							oTestDataConfig['sys_id'] = sSysId;
						} else if (bError) {
							gs.error('GlobalToolsATF.generateTestData error creating test data: ' + JSON.stringify(oError));
						} // if sys id
					}, this); // each record
				} // if valid data cfg
			}, this); // each table
		} // if cfg
	}, // function generateTestData

	addError: function (sFunction, sError) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		this._aErrors.push(this._sScriptIncludeName + '.' + sFunction + ' ' + sError);
	}, // function addError

	// Strict OpenAPI 3.0 subset (type, integer, nullable, enum, required, properties, additionalProperties, items, oneOf):
	// a property the schema does not declare is an error unless additionalProperties allows it
	validateSchema: function (oValue, oSchema) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		var fnValidate = function (oNodeValue, oNodeSchema, sPath, aNodeErrors) {
			if (!oNodeSchema) {
				return aNodeErrors;
			} // if no schema
			if (Array.isArray(oNodeSchema['oneOf'])) {
				var iMatches = oNodeSchema['oneOf'].filter(function (oOption) {
					return (fnValidate(oNodeValue, oOption, sPath, []).length == 0);
				}).length; // each option
				if (iMatches == 0) {
					aNodeErrors.push(sPath + ': no oneOf option matches ' + String(JSON.stringify(oNodeValue)).substring(0, 200));
				} // if no option
				return aNodeErrors;
			} // if oneOf
			if (oNodeValue === null) {
				if (oNodeSchema['nullable'] !== true) {
					aNodeErrors.push(sPath + ': null but not nullable');
				} // if not nullable
				return aNodeErrors;
			} // if null
			var sType = oNodeSchema['type'];
			var sActualType = (Array.isArray(oNodeValue)) ? 'array' : typeof oNodeValue;
			if ((sType == 'integer') && ((sActualType != 'number') || (Math.floor(oNodeValue) !== oNodeValue))) {
				aNodeErrors.push(sPath + ': expected integer, got ' + sActualType + ' ' + String(JSON.stringify(oNodeValue)));
				return aNodeErrors;
			} else if ((sType) && (sType != 'integer') && (sType != sActualType)) {
				aNodeErrors.push(sPath + ': expected ' + sType + ', got ' + sActualType + ' ' + String(JSON.stringify(oNodeValue)).substring(0, 200));
				return aNodeErrors;
			} // if type mismatch
			if ((Array.isArray(oNodeSchema['enum'])) && (oNodeSchema['enum'].indexOf(oNodeValue) == -1)) {
				aNodeErrors.push(sPath + ': value ' + String(JSON.stringify(oNodeValue)) + ' not in enum');
			} // if enum
			if (sActualType == 'object') {
				var oProperties = oNodeSchema['properties'] || {};
				(oNodeSchema['required'] || []).forEach(function (sRequired) {
					if (!Object.prototype.hasOwnProperty.call(oNodeValue, sRequired)) {
						aNodeErrors.push(sPath + ': missing required property ' + sRequired);
					} // if missing
				}); // each required
				Object.keys(oNodeValue).forEach(function (sKey) {
					if (Object.prototype.hasOwnProperty.call(oProperties, sKey)) {
						fnValidate(oNodeValue[sKey], oProperties[sKey], sPath + '.' + sKey, aNodeErrors);
					} else if ((oNodeSchema['additionalProperties']) && (typeof oNodeSchema['additionalProperties'] == 'object')) {
						fnValidate(oNodeValue[sKey], oNodeSchema['additionalProperties'], sPath + '.' + sKey, aNodeErrors);
					} else if ((oNodeSchema['additionalProperties'] !== true) && ((oNodeSchema['properties']) || (oNodeSchema['additionalProperties'] === false))) {
						aNodeErrors.push(sPath + ': undeclared property ' + sKey);
					} // if declared, allowed or undeclared
				}); // each value key
			} else if (sActualType == 'array') {
				oNodeValue.forEach(function (oItem, iIndex) {
					fnValidate(oItem, oNodeSchema['items'], sPath + '[' + iIndex + ']', aNodeErrors);
				}); // each item
			} // if object or array
			return aNodeErrors;
		}; // function fnValidate (closure recursion, this.validateSchema recursion would lose the error array)
		return fnValidate(oValue, oSchema, '$', []);
	}, // function validateSchema

	// Without reExpectedError the value must match the schema; with it, one validation error must match (negative control)
	checkSchema: function (sLabel, oValue, oSchema, reExpectedError) {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if (this._bContinue === false) { return; }
		this._iTestCount++;
		var aErrors = this.validateSchema(oValue, oSchema);
		var bExpectError = (this._getType(reExpectedError) == 'regexp');
		var bPassed = (bExpectError) ? (reExpectedError.test(aErrors.join('\n'))) : (aErrors.length == 0);
		if (this._bLog) {
			gs.info(this._sScriptIncludeName + '.checkSchema ' + sLabel + ' passed: ' + bPassed + ' errors: ' + JSON.stringify(aErrors));
		} // if log
		if (!bPassed) {
			this._aErrors.push(this._sScriptIncludeName + '.checkSchema test counter ' + this._iTestCount + ' ' + sLabel + ((bExpectError) ? ' expected an error matching ' + reExpectedError.toString() : '') + ' errors: ' + JSON.stringify(aErrors.slice(0, 15)) + ' value: ' + String(JSON.stringify(oValue)).substring(0, 1500));
		} // if failed
		return bPassed;
	}, // function checkSchema

	endATF: function () {
		if (!this._checkAccess(gs.getCallerScopeName())) { return; }
		if (this._aErrors.length > 0) {
			this._stepResult.setOutputMessage(this._aErrors.join('\n'));
			return false;
		} else {
			return true;
		}
	}, // function endATF

	type: 'GlobalToolsATF',
	version: '2.1.5',
	author: 'Tom Hauri',
	email: 'tom@hauri.biz'
};
